TriggerOraclev10g.body:
-- ========================================== -- 1. DECLARATION SECTION -- ========================================== -- Define a record structure to hold the :NEW values we need to validate TYPE t_timetable_rec IS RECORD ( school_code school_timetable_log.school_code%TYPE, batch_no school_timetable_log.batch_no%TYPE, timetable_ver_id school_timetable_log.timetable_ver_id%TYPE, term_code school_timetable_log.term_code%TYPE, year_date school_timetable_log.year_date%TYPE, period_no school_timetable_log.period_no%TYPE, employee_id school_timetable_log.employee_id%TYPE, substitute_id school_timetable_log.employee_id%TYPE, class_code school_timetable_log.class_code%TYPE, section_code school_timetable_log.section_code%TYPE, stream_code school_timetable_log.stream_code%TYPE );
-- Define a collection (nested table) of the record type TYPE t_timetable_tab IS TABLE OF t_timetable_rec;
-- Instantiate the collection variable v_new_rows t_timetable_tab := t_timetable_tab();
-- ========================================== -- 2. AFTER EACH ROW SECTION -- ========================================== AFTER EACH ROW IS BEGIN -- FIX: Instead of checking and returning, invert the logic. -- Only process and cache the record if it is NOT a Lunch Period (10) AND employee_id is NOT NULL. IF :new.subject_code IS NOT NULL AND :new.employee_id IS NOT NULL THEN
-- Extend the collection and store the :NEW row values for later v_new_rows.extend; v_new_rows(v_new_rows.last).school_code := :new.school_code; v_new_rows(v_new_rows.last).batch_no := :new.batch_no; v_new_rows(v_new_rows.last).timetable_ver_id := :new.timetable_ver_id; v_new_rows(v_new_rows.last).term_code := :new.term_code; v_new_rows(v_new_rows.last).year_date := :new.year_date; v_new_rows(v_new_rows.last).period_no := :new.period_no; v_new_rows(v_new_rows.last).employee_id := :new.employee_id; v_new_rows(v_new_rows.last).substitute_id := :new.substitute_id; v_new_rows(v_new_rows.last).class_code := :new.class_code; v_new_rows(v_new_rows.last).section_code := :new.section_code; v_new_rows(v_new_rows.last).stream_code := :new.stream_code; END IF; END AFTER EACH ROW;
-- ========================================== -- 3. AFTER STATEMENT SECTION -- ========================================== AFTER STATEMENT IS v_existing_class_info VARCHAR2(100); v_teacher_name VARCHAR2(100); BEGIN -- Loop through the collected rows. The table is no longer mutating here. FOR i IN 1..v_new_rows.count LOOP BEGIN -- Run your conflict validation query against the collection data SELECT csec.pseudo_name || '[Period ' || stt.period_no || ']' INTO v_existing_class_info FROM school_timetable_log stt INNER JOIN class_section csec ON ( csec.school_code = stt.school_code AND csec.batch_no# = stt.batch_no AND csec.class_code = stt.class_code AND csec.stream_code = stt.stream_code AND csec.section_code = stt.section_code ) WHERE stt.school_code = v_new_rows(i).school_code AND stt.batch_no = v_new_rows(i).batch_no AND stt.timetable_ver_id = v_new_rows(i).timetable_ver_id AND stt.term_code = v_new_rows(i).term_code AND stt.year_date = v_new_rows(i).year_date AND stt.period_no = v_new_rows(i).period_no AND stt.employee_id = v_new_rows(i).employee_id AND nvl(stt.substitute_id, -1) = nvl(v_new_rows(i).substitute_id, -1) AND ( stt.class_code != v_new_rows(i).class_code OR stt.section_code != v_new_rows(i).section_code OR stt.stream_code != v_new_rows(i).stream_code ) AND ROWNUM = 1;
-- If the SELECT above finds data, it means there IS a conflict. -- Fetch the teacher's name. SELECT first_name || nvl2(middle_name, ' ' || middle_name || ' ', ' ') || last_name INTO v_teacher_name FROM employee WHERE id = v_new_rows(i).substitute_id AND ROWNUM = 1;
-- Raise the application error, rolling back the statement raise_application_error(-20001, 'Teacher: ' || v_teacher_name || ' is already assigned to a different class (' || v_existing_class_info || ') during this period.');
EXCEPTION WHEN no_data_found THEN -- No conflicting class found, assignment is valid. -- Exception caught cleanly; the loop simply moves to the next record. NULL; END; END LOOP;
-- Free up memory once the statement checks are done v_new_rows.DELETE; END AFTER STATEMENT; END school_timetable_log_double_trg;
